]

background = 8

def solve(grid):
    # Find columns where multiple rows have 5
    col_to_rows = {}
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 5:
                col_to_rows.setdefault(c, set()).add(r)

    multi_row_cols = {c for c, rows in col_to_rows.items() if len(rows) > 1}

    # Output: replace overlapping cells with background, keep others
    output = []
    for r in range(len(grid)):
        new_row = []
        for c in range(len(grid[r])):
            if grid[r][c] == 5 and c in multi_row_cols:
                new_row.append(background)  # Overlapping → background
            else:
                new_row.append(grid[r][c])
        output.append(new_row)
    return output

output_v4 = solve(grid)
print("Extract v4 (replace overlaps with background):")
